css:
.vn-root{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:44px;font-family:var(--vn-font);overflow:hidden;}
.vn-bg{position:absolute;inset:0;background:radial-gradient(circle at 20% 50%,rgba(34,211,238,.22),transparent 42%),radial-gradient(circle at 80% 50%,rgba(244,114,182,.22),transparent 42%),linear-gradient(160deg,rgba(4,6,12,.97),rgba(10,5,18,.985));}
.vn-bg:after{content:'';position:absolute;inset:0;background:repeating-linear-gradient(180deg,rgba(255,255,255,.035) 0 1px,transparent 1px 5px);}
.vn-grid{position:absolute;inset:0;background-image:linear-gradient(rgba(34,211,238,.09) 1px,transparent 1px),linear-gradient(90deg,rgba(244,114,182,.08) 1px,transparent 1px);background-size:80px 80px;mask-image:radial-gradient(ellipse at 50% 50%,#000 20%,transparent 78%);-webkit-mask-image:radial-gradient(ellipse at 50% 50%,#000 20%,transparent 78%);opacity:.55;}
.vn-round{position:relative;z-index:2;font-size:var(--vn-round-size);font-weight:700;letter-spacing:10px;color:var(--vn-accent);text-transform:uppercase;text-shadow:0 0 16px var(--vn-accent);}
.vn-round:empty{display:none;}
.vn-body{position:relative;z-index:2;display:flex;align-items:center;gap:56px;}
.vn-side{display:flex;flex-direction:column;align-items:center;gap:26px;width:520px;}
.vn-avatar{position:relative;width:var(--vn-avatar-size);height:var(--vn-avatar-size);border-radius:20px;overflow:hidden;background:linear-gradient(160deg,#071018,#160a1a);display:flex;align-items:center;justify-content:center;}
.vn-left .vn-avatar{box-shadow:0 0 0 2px var(--vn-cyan),0 0 30px rgba(34,211,238,.55),inset 0 0 30px rgba(34,211,238,.18);}
.vn-right .vn-avatar{box-shadow:0 0 0 2px var(--vn-magenta),0 0 30px rgba(244,114,182,.55),inset 0 0 30px rgba(244,114,182,.18);}
.vn-avatar img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;display:none;z-index:1;}
.vn-avatar img.is-ready{display:block;}
.vn-fallback{position:relative;z-index:0;font-size:76px;font-weight:900;color:rgba(255,255,255,.35);}
.vn-name{font-size:var(--vn-name-size);font-weight:800;color:#fff;letter-spacing:1px;text-align:center;line-height:1.12;max-width:520px;word-break:break-word;}
.vn-left .vn-name{text-shadow:0 0 12px rgba(34,211,238,.75),0 0 36px rgba(34,211,238,.35);}
.vn-right .vn-name{text-shadow:0 0 12px rgba(244,114,182,.75),0 0 36px rgba(244,114,182,.35);}
.vn-mid{position:relative;width:200px;display:flex;align-items:center;justify-content:center;flex:0 0 auto;}
.vn-diamond{position:absolute;width:150px;height:150px;border:2px solid rgba(255,255,255,.16);transform:rotate(45deg);box-shadow:0 0 26px rgba(34,211,238,.25),0 0 26px rgba(244,114,182,.2);}
.vn-vs{position:relative;z-index:2;font-size:84px;font-weight:900;font-style:italic;letter-spacing:2px;color:#fff;text-shadow:0 0 14px var(--vn-cyan),0 0 36px rgba(34,211,238,.55),0 0 60px var(--vn-magenta),0 6px 26px rgba(0,0,0,.7);}
.vn-team{display:flex;align-items:center;gap:14px;max-width:520px;}
.vn-team:not(:has(.vn-team-name:not(:empty),img.is-ready)){display:none;}
.vn-team-logo{position:relative;width:var(--vn-team-logo);height:var(--vn-team-logo);flex:0 0 auto;display:flex;align-items:center;justify-content:center;border-radius:8px;}
.vn-left .vn-team-logo:has(img.is-ready){overflow:hidden;background:#071018;box-shadow:0 0 0 1px var(--vn-cyan),0 0 18px rgba(34,211,238,.55);}
.vn-right .vn-team-logo:has(img.is-ready){overflow:hidden;background:#160a1a;box-shadow:0 0 0 1px var(--vn-magenta),0 0 18px rgba(244,114,182,.55);}
.vn-team-logo img{width:100%;height:100%;object-fit:contain;display:none;}
.vn-team-logo img.is-ready{display:block;}
.vn-team-fallback{width:8px;height:8px;border-radius:50%;}
.vn-left .vn-team-fallback{background:var(--vn-cyan);box-shadow:0 0 10px var(--vn-cyan);}
.vn-right .vn-team-fallback{background:var(--vn-magenta);box-shadow:0 0 10px var(--vn-magenta);}
.vn-team-logo:has(img.is-ready) .vn-team-fallback{display:none;}
.vn-team-name{font-size:var(--vn-team-size);font-weight:800;letter-spacing:3px;line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0;}
.vn-left .vn-team-name{color:var(--vn-cyan);text-shadow:0 0 10px rgba(34,211,238,.8),0 0 26px rgba(34,211,238,.4);}
.vn-right .vn-team-name{color:var(--vn-magenta);text-shadow:0 0 10px rgba(244,114,182,.8),0 0 26px rgba(244,114,182,.4);}
.vn-team-name:empty{display:none;}
